import json,pathlib,hashlib
E=pathlib.Path(__file__).resolve().parent
load=lambda p:json.loads((E/p).read_text())
def save(p,x):(E/p).write_text(json.dumps(x,indent=2)+'\n')
inspected=['render/question-001.png','render/question-003.png','render/question-004.png','render/question-016.png','render/question-020.png','render/question-061.png','render/question-076.png','render/question-078.png']
save('render-inspection.json',{'automated_cases':86,'renderer_passed':True,'visually_inspected':inspected,'observations':'Readable matrix size, rank/nullity and dim(Null(A)) notation; five radio controls and complete theorem/substitution/subtraction solution. Inspected same consecutive bank with answers 5 and 9, row-only 10->12 pair with unchanged answer 6, full-rank nullity zero, nullity-supplied zero, and both requested targets. No clipping, missing glyphs or unresolved TeX observed. Actual UI shuffles display order; numerical bank-role tests do not depend on it.','limits':'Offline preview displays completed responses/solutions. Native learner grading is separately exercised with all authored choice UUIDs.','dependency_results':'render-dependency-results.json'})
src=load('source-analysis.json')
result={'verdict':'accepted','summary':'Both retained defects are repaired. All eight checks pass, including all 14 source banks, controlled answer-role variation, native grading, actual UI rendering, and the exact five-question batch. Package unchanged.','source_analysis':{k:src[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']},'checks':{},'findings':[]}
checks={
'source_replay':(['source-analysis.json','source-replay.json','source-replay-records.json','canonical-example.json','regression-comparison.json'],'All 14 target prompts, full banks, keys and worked solutions replay. Canonical numerical parameters/stages verified; its source bank is absent. Three historical missing cases reproduce on the old executable and pass now.'),
'math':(['math-and-coverage.json','boundary-tests.json','counterfactual-results.json'],'Visible prompts, exact subtraction, matrix feasibility, five distinct choices and solution dependencies independently verified on 287 records plus explicit boundaries. No mathematical failures.'),
'variety':(['coverage.json','independent-samples.json','delivery-control/delivery.json','delivery-shortcut-results.json'],'All 14 profiles and all five correct numerical bank roles tested. Both targets and tall/wide/square shapes survive shared delivery filtering: 170 controls become 166; exact batch remains 5.'),
'scope':(['source-analysis.json','scope-review.json','rejection-and-replay.json','boundary-tests.json'],'Retains easy single-theorem subtraction and five-choice radio responses. Same-method boundary extensions justified; unsupported difficulties and free-entry format reject.'),
'grading':(['grader-input.json','grader-report.json','counterfactual-results.json'],'Actual native grader: 207 accepted and 828 rejected choice responses, zero unresolved. Complete raw/normalized paired banks, source banks and exact batch tested. Source response is radio; free-entry equivalence is inapplicable.'),
'rendering':(['render/rendering.json','render-inspection.json','render-dependency-results.json'],'86 actual-UI previews pass; all rendered prompt/solution dependencies verified. Representative screenshots visually inspected for readable notation, radio controls and full worked solutions.'),
'packaging':(['packaging-tests.json','package-integrity.json','package-before.json','package-after.json','rejection-and-replay.json'],'Declared runtime matches Python 3.13.5 with no third-party dependencies. Relocated declared files replay deterministically. Every workspace file remains unchanged; no database writes or asset publication.'),
'decision_variation':(['pedagogical-variation.json','evidence-contract.json','counterfactual-results.json','delivery-shortcut-results.json','learner-selection.json','inventory-audit.json','affected-inventory.json','regression-comparison.json'],'Relevant given changes exercise all five roles with bank/size fixed; row-only changes preserve response. Old shortcut fails on revised controls and answers 1/5 exact batch members. Every surviving control signature has all five roles. Captured inventory has 14 originals and zero generated items. Selection assessed conditionally under actual all-easy rules; live policy/history and future inventory remain outside captured evidence.')}
for name,(paths,details) in checks.items():
 assert all((E/p).is_file() and (E/p).stat().st_size>0 for p in paths)
 result['checks'][name]={'status':'passed','evidence_paths':paths,'details':details}
assert len(result['checks'])==8
save('result.json',result)
save('review-binding.json',{'policy_version':2,'package_hash':'b40c992a51ed4eda0db6a986a9f860b13cc60d9f164bbdb98253a33224246774','batch_hash':'fae918b1679797b1b823319e2e36c60a0eca1ce54109170aceeea3693fea9a1f','source_hash':'16f606a905e43ae6a8a5d0701d6f7c867b3dcb4f0b3c34b7b7fcd44549e078e3','inventory_hash':'f8acd047dfd1ac1d4aeb7a1200f9fc86bca194a0d78ae2c8d80d767c4315ae3a','effective_difficulty':'easy','engine_hash':'dc1e0a8583ca33c6028bc0a641128ecc8e7896742189dd42b292170c9726bad9','assets':{}})
# Last integrity verification after all execution completed.
W=E.parent/'workspace';after={str(p.relative_to(W)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(W.rglob('*')) if p.is_file()};assert after==load('package-before.json')
(E/'session-state.md').write_text('Review complete: accepted. All 8 checks pass; result.json contains final report. Both retained defects were reproduced on prior executable and tested against current package. Source 14/14; native 207 accepted +828 rejected; UI 86/86; delivered control 166 and batch 5. Pedagogical schema validated. All '+str(len(after))+' workspace files unchanged. No database writes/publication.\n')
print(json.dumps({'verdict':result['verdict'],'checks':list(result['checks']),'workspace_files_unchanged':len(after),'report':'result.json'}))
